makeMtLab(document.getElementById("lab-l13"),{id:"l13",scenarios:[{"label": "Ví dụ: A của ca mẫu", "note": "Thời gian chạy chia thời gian kế hoạch.", "steps": [{"t": "Thời gian chạy 390, kế hoạch 450", "html": "<p class=\"mt-calc\">A = 390 / 450<\/p>"}, {"t": "Kết quả", "html": "<p class=\"mt-calc\">A ≈ <b>0,8667<\/b><\/p>", "ask": {"q": "A bằng bao nhiêu?", "o": ["0,8667", "0,7556", "1,1538"], "a": 0}}]}, {"label": "Ví dụ: Cộng sự kiện RUNNING", "note": "Chỉ cộng phần nằm trong thời gian kế hoạch.", "steps": [{"t": "Ba sự kiện RUNNING", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Từ<\/th><th scope=\"col\">Tới<\/th><th scope=\"col\">Phút<\/th><\/tr><\/thead><tbody><tr><td>06:00<\/td><td>09:00<\/td><td>180<\/td><\/tr><tr><td>09:40<\/td><td>12:30<\/td><td>170<\/td><\/tr><tr><td>12:50<\/td><td>14:00<\/td><td>70<\/td><\/tr><\/tbody><\/table>"}, {"t": "Trừ giờ nghỉ khỏi sự kiện thứ hai", "html": "<p class=\"mt-calc\">170 − 30 = 140<\/p>", "ask": {"q": "Sự kiện 09:40–12:30 chứa nghỉ 10:00–10:30. Tính bao nhiêu phút?", "o": ["170", "140", "110"], "a": 1}}, {"t": "Tổng", "html": "<p class=\"mt-calc\">180 + 140 + 70 = <b>390 phút<\/b><\/p>"}]}, {"label": "Ví dụ: Máy không dừng", "note": "A = 1 là giới hạn trên.", "steps": [{"t": "RUNNING suốt thời gian kế hoạch", "html": "<p class=\"mt-calc\">Chạy = 450<\/p>"}, {"t": "A = 1", "html": "<p class=\"mt-calc\">A không thể lớn hơn 1<\/p>", "say": "<p>Nếu A > 1, thời gian kế hoạch hoặc sự kiện bị tính sai.<\/p>"}]}, {"label": "Bẫy: Tính NO_DATA là dừng", "note": "Mất kết nối không có nghĩa là máy dừng.", "steps": [{"t": "Rút cáp mạng 30 phút", "html": "<p class=\"mt-calc\">Collector ghi NO_DATA 30 phút<\/p>"}, {"t": "Nếu tính là DOWN", "html": "<p class=\"mt-calc\">A giảm 30/450 ≈ 6,7 điểm % mà không chắc máy dừng<\/p>", "ask": {"q": "Nên xử lý NO_DATA thế nào?", "o": ["Tính là dừng", "Tính là chạy", "Báo riêng, không tính vào A"], "a": 2}}]}, {"label": "Lỗi: Công nhân làm tròn giờ dừng", "note": "Dừng 09:02–09:37 ghi thành 09:00–09:30.", "steps": [{"t": "Sổ tay ghi 30 phút", "html": "<p class=\"mt-calc\">Thực tế 35 phút<\/p>"}, {"t": "A sai", "html": "<p class=\"mt-calc\">A ghi = 420/450 = 0,9333; A thật = 415/450 ≈ 0,9222<\/p>", "say": "<p>Lấy thời điểm từ PLC, người chỉ gán lý do.<\/p>"}]}]});
